=== FILE: skid_buffer.v ===
// skid_buffer: two-register valid/ready slice (register slice).
// Implements interface_spec.md and microarchitecture.md (approved).
// Every output is a flop or the inverse of one: s_ready = !skid_valid,
// m_valid and m_data are registers. Inputs reach only next-state logic.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat is accepted on this edge.
    wire s_fire = s_valid && s_ready;

    assign s_ready = !skid_valid;

    // Next state, microarchitecture section 3.
    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // The skid beat (the older of what remains) moves out.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // Skid empty: s_ready is high, so s_fire equals s_valid.
                m_valid_d    = s_valid;
                m_data_d     = s_data;
            end
        end else if (s_fire) begin
            // Output stalled with one beat: catch the new beat.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: no reset (microarchitecture section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

`ifdef FORMAL
    // Design-intent assertions (not a proof setup; no .sby is submitted).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // The skid register is only full while the output register is full.
    always @(*) begin
        if (f_past_valid) assert(!skid_valid || m_valid);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end else if ($past(m_valid) && !$past(m_ready)) begin
                // A stalled beat holds.
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) cover(skid_valid && m_ready);
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: skid_buffer_tb.v ===
// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
// Checks every cycle against a queue model of up to two beats.
`timescale 1ns/1ps
`default_nettype none

`define CHECK(c, m) begin if (c) passed = passed + 1; else begin failed = failed + 1; $error(m); end end

module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    integer        passed;
    integer        failed;
    reg [8*64-1:0] nonce;

    // Queue model.
    reg [7:0] q0;
    reg [7:0] q1;
    integer   cnt;
    reg       model_known;
    reg       prev_stall;
    reg [7:0] prev_data8;
    reg       prev_data1;

    // Values sampled just before each edge.
    reg       pre_s_ready;
    reg       pre_m_valid;
    reg [7:0] pre_m_data8;
    reg       pre_m_data1;
    reg       fire_s;
    reg       fire_m;

    // Snapshot for the in-cycle stability check.
    reg       g_s_ready8;
    reg       g_m_valid8;
    reg [7:0] g_m_data8;
    reg       g_s_ready1;
    reg       g_m_valid1;
    reg       g_m_data1;

    integer    n_s_fire;
    integer    n_m_fire;
    integer    n_full;
    integer    n_stall;
    integer    i;
    integer    k;
    integer    base_s;
    integer    base_m;
    reg [31:0] rs;
    reg        rv;
    reg        rr;
    reg        rn;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task rnd;
        begin
            rs = rs ^ (rs << 13);
            rs = rs ^ (rs >> 17);
            rs = rs ^ (rs << 5);
        end
    endtask

    task check_outputs;
        begin
            if (model_known) begin
                `CHECK(m_valid8 === (cnt > 0), "W8: m_valid does not match the beats held")
                `CHECK(s_ready8 === (cnt < 2), "W8: s_ready does not match the beats held")
                `CHECK(m_valid1 === (cnt > 0), "W1: m_valid does not match the beats held")
                `CHECK(s_ready1 === (cnt < 2), "W1: s_ready does not match the beats held")
                if (cnt > 0) begin
                    `CHECK(m_data8 === q0, "W8: m_data is not the oldest beat held")
                    `CHECK(m_data1 === q0[0:0], "W1: m_data is not the oldest beat held")
                end
                if (prev_stall) begin
                    `CHECK(m_valid8 === 1'b1 && m_data8 === prev_data8, "W8: stalled beat did not hold")
                    `CHECK(m_valid1 === 1'b1 && m_data1 === prev_data1, "W1: stalled beat did not hold")
                end
            end
        end
    endtask

    // One clock cycle: apply inputs, check, glitch-check, sample, edge, model.
    task cycle;
        input       sv;
        input [7:0] sd;
        input       mr;
        input       rnn;
        begin
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            rst_n   = rnn;
            #2;
            check_outputs;
            g_s_ready8 = s_ready8;
            g_m_valid8 = m_valid8;
            g_m_data8  = m_data8;
            g_s_ready1 = s_ready1;
            g_m_valid1 = m_valid1;
            g_m_data1  = m_data1;
            s_valid = !sv;
            m_ready = !mr;
            #1;
            if (model_known) begin
                `CHECK(s_ready8 === g_s_ready8, "W8: s_ready moved with m_ready or s_valid inside a cycle")
                `CHECK(m_valid8 === g_m_valid8, "W8: m_valid moved with an input inside a cycle")
                `CHECK(m_data8 === g_m_data8, "W8: m_data moved with an input inside a cycle")
                `CHECK(s_ready1 === g_s_ready1, "W1: s_ready moved with m_ready or s_valid inside a cycle")
                `CHECK(m_valid1 === g_m_valid1, "W1: m_valid moved with an input inside a cycle")
                `CHECK(m_data1 === g_m_data1, "W1: m_data moved with an input inside a cycle")
            end
            s_valid = sv;
            m_ready = mr;
            #1;
            pre_s_ready = s_ready8;
            pre_m_valid = m_valid8;
            pre_m_data8 = m_data8;
            pre_m_data1 = m_data1;
            fire_s = sv && s_ready8;
            fire_m = m_valid8 && mr;
            @(posedge clk);
            if (!rnn) begin
                cnt         = 0;
                model_known = 1'b1;
                prev_stall  = 1'b0;
            end else if (model_known) begin
                prev_stall = pre_m_valid && !mr;
                prev_data8 = pre_m_data8;
                prev_data1 = pre_m_data1;
                if (fire_m) begin
                    n_m_fire = n_m_fire + 1;
                    if (cnt > 0) begin
                        q0  = q1;
                        cnt = cnt - 1;
                    end
                end
                if (fire_s) begin
                    n_s_fire = n_s_fire + 1;
                    `CHECK(cnt < 2, "a beat was accepted while two were held")
                    if (cnt == 0) q0 = sd;
                    else if (cnt == 1) q1 = sd;
                    if (cnt < 2) cnt = cnt + 1;
                end
            end
            #1;
        end
    endtask

    initial begin
        passed      = 0;
        failed      = 0;
        nonce       = {(8*64){1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {(8*64){1'b0}};
        q0          = 8'h00;
        q1          = 8'h00;
        cnt         = 0;
        model_known = 1'b0;
        prev_stall  = 1'b0;
        prev_data8  = 8'h00;
        prev_data1  = 1'b0;
        n_s_fire    = 0;
        n_m_fire    = 0;
        n_full      = 0;
        n_stall     = 0;
        rs          = 32'h1234_5678;
        s_valid     = 1'b0;
        s_data      = 8'h00;
        m_ready     = 1'b0;
        rst_n       = 1'b0;

        // 1. Reset values.
        cycle(1'b0, 8'h00, 1'b0, 1'b0);
        cycle(1'b1, 8'hFF, 1'b0, 1'b0);
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b0, "m_valid not low after reset")
        `CHECK(pre_s_ready === 1'b1, "s_ready not high after reset")

        // 2. One-cycle latency.
        cycle(1'b1, 8'hA5, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b0, "beat offered in the cycle it was accepted")
        `CHECK(fire_s === 1'b1, "empty slice did not accept a beat")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b1 && pre_m_data8 === 8'hA5, "beat not offered one cycle after acceptance")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b0, "slice did not return to idle")

        // 3. Long stream at full throughput.
        base_s = n_s_fire;
        base_m = n_m_fire;
        for (i = 0; i < 64; i = i + 1) begin
            cycle(1'b1, i[7:0], 1'b1, 1'b1);
            `CHECK(pre_s_ready === 1'b1, "s_ready dropped at full throughput")
            if (i > 0) `CHECK(pre_m_valid === 1'b1, "output bubble at full throughput")
        end
        `CHECK(n_s_fire - base_s == 64, "not one beat in per cycle at full throughput")
        `CHECK(n_m_fire - base_m == 63, "not one beat out per cycle at full throughput")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(cnt == 0, "stream did not drain")

        // 4. Stall with one beat held, then two.
        cycle(1'b1, 8'h11, 1'b1, 1'b1);
        cycle(1'b1, 8'h22, 1'b0, 1'b1);
        `CHECK(pre_m_valid === 1'b1 && pre_s_ready === 1'b1, "second beat refused with one beat held")
        `CHECK(fire_s === 1'b1, "second beat not accepted during stall")
        cycle(1'b1, 8'h33, 1'b0, 1'b1);
        `CHECK(pre_s_ready === 1'b0, "third beat offered s_ready with two held")
        `CHECK(fire_s === 1'b0, "third beat accepted with two held")
        for (k = 0; k < 4; k = k + 1) begin
            cycle(1'b1, 8'hE0 + k[7:0], 1'b0, 1'b1);
            `CHECK(pre_s_ready === 1'b0, "s_ready rose while full and stalled")
            `CHECK(pre_m_data8 === 8'h11, "stalled beat changed")
        end
        cycle(1'b1, 8'h33, 1'b1, 1'b1);
        `CHECK(pre_s_ready === 1'b0 && pre_m_data8 === 8'h11, "wrong state on the first ready after a full stall")
        cycle(1'b1, 8'h33, 1'b1, 1'b1);
        `CHECK(pre_s_ready === 1'b1 && pre_m_data8 === 8'h22, "skid beat not second out or ready not risen")
        `CHECK(fire_s === 1'b1, "beat not accepted after ready rose")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b1 && pre_m_data8 === 8'h33, "third beat not out in order")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b0, "slice not idle after stall drain")

        // 5. Stream with a one-cycle and a multi-cycle stall.
        for (i = 0; i < 24; i = i + 1) begin
            rr = !(i == 5 || (i >= 12 && i < 17));
            cycle(1'b1, 8'h80 + i[7:0], rr, 1'b1);
        end
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(cnt == 0, "stalled stream did not drain")

        // 6. Reset with beats held.
        cycle(1'b1, 8'h44, 1'b0, 1'b1);
        cycle(1'b1, 8'h55, 1'b0, 1'b1);
        `CHECK(cnt == 2, "two beats not held before reset")
        cycle(1'b1, 8'h66, 1'b0, 1'b0);
        cycle(1'b1, 8'h77, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b0 && pre_s_ready === 1'b1, "reset did not drop held beats")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);
        `CHECK(pre_m_valid === 1'b1 && pre_m_data8 === 8'h77, "first beat after reset wrong")
        cycle(1'b0, 8'h00, 1'b1, 1'b1);

        // 7. Random traffic against the model, with rare resets.
        for (i = 0; i < 4000; i = i + 1) begin
            rnd;
            rv = (rs[1:0] != 2'b00);
            case ((i / 500) % 4)
                0:       rr = (rs[3:2] != 2'b00);
                1:       rr = rs[2];
                2:       rr = (rs[3:2] == 2'b00);
                default: begin rr = 1'b1; rv = 1'b1; end
            endcase
            rn = (rs[31:22] != 10'd0);
            if (cnt == 2) n_full = n_full + 1;
            if (cnt > 0 && !rr) n_stall = n_stall + 1;
            cycle(rv, rs[15:8], rr, rn);
        end
        `CHECK(n_full > 0, "random traffic never filled the slice")
        `CHECK(n_stall > 0, "random traffic never stalled the output")

        // Drain.
        for (k = 0; k < 4; k = k + 1) begin
            cycle(1'b0, 8'h00, 1'b1, 1'b1);
        end
        `CHECK(cnt == 0, "random traffic did not drain")
        `CHECK(pre_m_valid === 1'b0, "m_valid still high after drain")
        `CHECK(pre_s_ready === 1'b1, "s_ready low after drain")

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
